{
  "driver_archetypes": [
    {
      "id": "moto_compliant",
      "base_vclass": "motorcycle",
      "distribution": "moto",
      "share": 0.8,
      "params": {
        "tau": 1.2,
        "minGap": 1.5,
        "speedFactor": 1.0,
        "speedDev": 0.05,
        "latAlignment": "center",
        "lcSublane": 1.0,
        "lcPushy": 0.0
      },
      "rationale": "Targets M4/overshoot_share (low overshoot for compliant) and M1/moto (standard discharge). Compliant riders stay in lane, respect gaps, and do not run red unless forced."
    },
    {
      "id": "moto_left_violator",
      "base_vclass": "motorcycle",
      "distribution": "moto",
      "share": 0.15,
      "params": {
        "tau": 2.8,
        "minGap": 2.4,
        "speedFactor": 0.9,
        "latAlignment": "left",
        "lcSublane": 3.5,
        "lcPushy": 0.6,
        "jmDriveAfterRedTime": 8.0,
        "jmDriveRedSpeed": 3.0
      },
      "rationale": "Targets M8/moto (wrong-lane share ~0.21) and M6/approach/l/moto (delayed entry). These riders seek space in lane 0/1, wait for opposing green to end, then cut left."
    },
    {
      "id": "car_compliant",
      "base_vclass": "passenger",
      "distribution": "car",
      "share": 0.95,
      "params": {
        "tau": 1.0,
        "minGap": 2.2,
        "speedFactor": 1.0,
        "speedDev": 0.08,
        "latAlignment": "center",
        "lcSublane": 1.0,
        "lcPushy": 0.0
      },
      "rationale": "Targets M1/car (discharge headway) and M2/early/car (negligible early start). Cars are patient, maintain central position, and rarely run red."
    },
    {
      "id": "car_violator",
      "base_vclass": "passenger",
      "distribution": "car",
      "share": 0.05,
      "params": {
        "tau": 2.5,
        "minGap": 1.8,
        "speedFactor": 0.95,
        "latAlignment": "left",
        "lcSublane": 2.5,
        "lcPushy": 0.4,
        "jmDriveAfterRedTime": 5.0,
        "jmDriveRedSpeed": 6.0
      },
      "rationale": "Targets M3/share/car (red-running share ~0.0076). Rare cars that are impetuous and run red when front-row or swarmed."
    }
  ],
  "traci_rules": [
    {
      "rule_type": "early_start",
      "applies_to": ["moto_compliant", "car_compliant", "moto_left_violator", "car_violator"],
      "params": {
        "t_before_green": 6.0,
        "p": 0.15,
        "v_max": 2.5
      },
      "rationale": "Targets M2/early/moto (share ~0.147) and M2/early/car (share ~0.0025). Motorcycles creep earlier than cars; violators creep more often."
    },
    {
      "rule_type": "swarm_red_running",
      "applies_to": ["moto_compliant", "car_compliant", "moto_left_violator", "car_violator"],
      "params": {
        "p0": 0.08,
        "k": 0.35,
        "p_max": 0.6,
        "dt": 20.0
      },
      "rationale": "Targets M3/share/moto (red-running share ~0.076) and M3/var_to_mean (variance/mean ~1.03). Swarm effect makes red-running contagious among motorcycles."
    },
    {
      "rule_type": "queue_space_seeking",
      "applies_to": ["moto_left_violator", "car_compliant"],
      "params": {
        "q": 60.0,
        "t_g_s": 10.0,
        "est_noise": 0.3,
        "p_wrong_lane": 0.25,
        "p_right_lane": 0.0,
        "p_sidewalk": 0.0,
        "v_creep": 3.0,
        "merge_zone_m": 15.0
      },
      "rationale": "Targets M8/moto (wrong-lane share) and M9a/per_cycle (straight vehicles in right-turn lane). Riders cut to lane 0/1 when queues block their movement."
    },
    {
      "rule_type": "illegal_left_box",
      "applies_to": ["moto_left_violator"],
      "params": {
        "release_lag_s": 3.5
      },
      "rationale": "Targets M7a/n_waiting (halters in box) and M6/junction/illegal_l/moto (delayed exit). Violators wait for opposing green to end before turning."
    },
    {
      "rule_type": "slow_lane_center",
      "applies_to": ["moto_compliant"],
      "params": {
        "lat_offset": 0.0
      },
      "rationale": "Targets M4/lat_moto (halting position ~7m) and M4/overshoot_share (overshoot ~2m). Compliant motorcycles ride centrally when stopped."
    },
    {
      "rule_type": "uturn_bypass",
      "applies_to": ["moto_compliant", "car_compliant"],
      "params": {
        "p": 0.85,
        "t_wait": 2.0
      },
      "rationale": "Targets M6/junction/u/moto (U-turn exit delay) and M11 (passing standing U-turner). Motorcycles frequently squeeze past U-turners."
    }
  ],
  "description": "Spec models mixed motorcycle/car traffic at Hanoi intersection with compliant and violator archetypes, implementing early-start creep, swarm red-running, wrong-lane queue dodging, illegal left-box waiting, central slow riding, and U-turn bypass to match observed metrics."
}

